/* From Uiverse.io by gharsh11032000 - Tags: button, search, hover effect */
.__UIV_SCOPE__ .button {
  position: relative;
  border: none;
  background-color: white;
  color: #212121;
  padding: 20px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 20px;
  font-weight: 600;
  gap: 10px;
  border-radius: 10px;
  transition: all 0.6s cubic-bezier(0.23, 1, 0.320, 1);
  box-shadow: 0 10px 20px rgba(0, 0, 0, 0.2);
  cursor: pointer;
  overflow: hidden;
}

.__UIV_SCOPE__ .button span {
  position: relative;
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 1;
}

.__UIV_SCOPE__ .button::before {
  content: "";
  position: absolute;
  background-color: palevioletred;
  width: 100%;
  height: 100%;
  left: 0%;
  bottom: 0%;
  transform: translate(-100%, 100%);
  border-radius: inherit;
}

.__UIV_SCOPE__ .button svg {
  fill: palevioletred;
  transition: all 0.6s cubic-bezier(0.23, 1, 0.320, 1);
}

.__UIV_SCOPE__ .button:hover::before {
  animation: shakeBack 0.6s forwards;
}

.__UIV_SCOPE__ .button:hover svg {
  fill: white;
  scale: 1.3;
}

.__UIV_SCOPE__ .button:active {
  box-shadow: none;
}

@keyframes shakeBack {
  0% {
    transform: translate(-100%, 100%);
  }

  50% {
    transform: translate(20%, -20%);
  }

  100% {
    transform: translate(0%, 0%);
  }
}
